145: export function inferSkillPhaseFromText(text, currentPhase = 'planning') {
146:     const lower = safeString(text).toLowerCase();
147:     if (!lower)
148:         return normalizeSkillPhase(currentPhase);
149:     const hasAny = (patterns) => patterns.some((p) => lower.includes(p));
150:     if (hasAny(['all tests pass', 'build succeeded', 'completed', 'complete', 'done', 'final summary', 'summary'])) {
151:         return 'completing';
152:     }
153:     if (hasAny(['verify', 'verified', 'verification', 'review', 'reviewed', 'diagnostic', 'typecheck', 'test'])) {
154:         return 'reviewing';
155:     }
156:     if (hasAny(['implement', 'implemented', 'apply patch', 'change', 'fix', 'update', 'refactor'])) {
157:         return 'executing';
158:     }
159:     if (hasAny(['plan', 'approach', 'steps', 'todo'])) {
160:         return 'planning';
161:     }
162:     return normalizeSkillPhase(currentPhase);
163: }
